"""How often each slow source is fetched: one list, read by collect.py and tools/watchdog.py (audit 2026-11-10 #48: a copy in watchdog raised a false cdec_res alarm)."""

# Slow history and reference data: refreshed at most once a day (owner 2026-10-25), in the 09:00-12:00 UTC full run, after USGS has
# computed yesterday's daily values everywhere in CONUS and before eastern-morning readers. A value older than 36 h refreshes on any run.
DAILY = {"snotel", "cpc", "cpc610", "usdm", "attains", "floodfreq", "acis", "ridb", "streamcat", "stocking", "rating", "uv", "dam_rise", "glsea", "usbr_lc", "usno", "usace_pool"}
WEEKLY = {"floods", "meta", "peaks", "wtemp", "record", "year", "fieldmeas", "multiyear", "wqp", "related"}  # related: the travel time between gauges from 8 days of readings (up to 6 USGS calls a gauge); the related gauges' live flows refresh hourly in fast_related. Weekly lifts the USGS key's gauge limit from about 1,000 to about 1,580 (pipeline audit #29, 2026-11-11)  # wqp: samples come weekly at most; daily at 14,000 gauges would be ~40,000 portal calls a day behind a firewall that blocks bursts  # USGS history, about 6 calls per gauge: daily would be 2,300 calls/h at 9,100 gauges on a 1,000/h key; weekly in 168 slots is 325/h
MONTHLY = {"access", "land", "cdec_res", "nid"}  # places that change over years; the slowest source when daily (Overpass took 101 of 192 s in a shard, 2026-10-31). 303 calls a day at 9,100 gauges. nid: the dam's own record (USACE National Inventory of Dams)
